referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const cells = Array.from({ length: d.length ?? d.text?.length ?? 0 }, () => null);
  for (const r of d.ranges) for (let i = r[0]; i < r[1]; i++) cells[i] = r[2];
  for (const e of d.edits ?? []) for (let i = e[0]; i < e[1]; i++) cells[i] = e[2];
  const out = [];
  for (let i = 0; i < cells.length; ) {
    let j = i + 1;
    while (j < cells.length && JSON.stringify(cells[j]) === JSON.stringify(cells[i])) j++;
    if (cells[i] !== null) out.push([i, j, cells[i]]);
    i = j;
  }
  return out;
}

